  {real: 0.7071, imag: 0},
  {real: 0, imag: 0.7071}
]
after = [
  {real: 0.7071, imag: 0},        // α₀ × 1
  {real: 0, imag: -0.7071}        // α₁ × (-1) = phase flip
]
// 이제 간섭이 물리적으로 정확함 ✓
```

